    except StopIteration:
        return

    initial_perm = []
    for _ in range(N):
        initial_perm.append(int(next(iterator)) - 1)  # Convert to 0-based

    swaps = set()
    for _ in range(M):
        u = int(next(iterator))
        v = int(next(iterator))
        swaps.add((u-1, v-1))  # Convert to 0-based

    target = list(range(N))
    start = tuple(initial_perm)
    end = tuple(target)

    if start == end:
        print(0)
        return

    # BFS to find minimum swaps
    queue = deque()
    queue.append((start, 0))
    visited = {start}

    while queue:
        current, dist = queue.popleft()
        current_list = list(current)

        for i in range(N):
            for j in range(i+1, N):
                if (i, j) in swaps:
                    # Perform swap
                    current_list[i], current_list[j] = current_list[j], current_list[i]
                    new_state = tuple(current_list)
                    if new_state == end:
                        print(dist + 1)
                        return
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append((new_state, dist + 1))
                    # Swap back to restore state for next iteration
                    current_list[i], current_list[j] = current_list[j], current_list[i]

